def _find_package_path(root_mod_name, import_name=None):
    try:
        spec = importlib.util.find_spec(root_mod_name)
        if spec is None:
            raise ValueError("not found")
    except (ImportError, ValueError):
        pass
    else:
        if spec.origin in {"namespace", None}:
            # if we have a more specific import name, try to resolve that
            if import_name:
                # get spec for the full import name
                sub_spec = importlib.util.find_spec(import_name)
                if sub_spec:
                    # if sub_spec is a regular package (has __init__) or module
                    if sub_spec.submodule_search_locations:
                        # package with __init__
                        return os.path.dirname(os.path.dirname(sub_spec.origin))
                    elif sub_spec.origin:
                        # module
                        return os.path.dirname(sub_spec.origin)
            # fallback to first location of namespace root
            return os.path.dirname(next(iter(spec.submodule_search_locations)))
        elif spec.submodule_search_locations:
            return os.path.dirname(os.path.dirname(spec.origin))
        else:
            return os.path.dirname(spec.origin)
    # rest of function unchanged, using loader etc.
```

